bolt_optional() {
  if "$@"; then
    return 0
  else
    bolt_optional_rc=$?
    case $bolt_optional_rc in
      129|130|143) exit "$bolt_optional_rc" ;;
      *) return 0 ;;
    esac
  fi
}

